import glob, importlib, traceback
fails=[]
for py in glob.glob(p+'/task-*.py'):
    tid=os.path.basename(py)[:-3]
    jf=p+'/'+tid+'.json'
    if not os.path.exists(jf): continue
    pairs=json.load(open(jf))
    try:
        ns={'__name__':'m'}
        exec(compile(open(py).read(),py,'exec'),ns)
        tr=ns['transform']
        bad=[i for i,pr in enumerate(pairs) if tr(pr['input'])!=pr['output']]
        if bad: fails.append((tid,bad))
    except Exception as e:
        fails.append((tid,repr(e)))
print('fails:',fails)
